public class Solution {
    public boolean isPowerOfThree(int n) {
        // If n is less than or equal to zero, then it cannot be a power of three
        if (n <= 0) {
            return false;
        }

        // Check if n is divisible by 3
        while (n % 3 == 0) {
            n /= 3; // Divide n by 3
